    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]

    for interval in intervals[1:]:
        last_end = merged[-1][1]
        if interval[0] <= last_end < interval[1]:
            # Merge by updating the end of the last merged interval
            merged[-1] = (merged[-1][0], interval[1])
        elif interval[0] > last_end:
            # No overlap, add the current interval to the list
            merged.append(interval)

